const accents=["#c9ff3d","#c9ff3d","#c9ff3d","#ffd052","#ffd052","#ff6a3d","#4774ff","#4774ff","#ff6a3d","#ff9d69","#45c8ef","#d8a759","#b695ff","#ff8eb6","#58d4b0","#ff875f","#74a3ff","#b695ff","#ff554f","#c9ff3d"];
TASK_FAMILIES.forEach(f=>f.tasks.forEach((t,i)=>{t.id=`F${String(f.n).padStart(2,"0")}-T${String(i+1).padStart(2,"0")}`}));

const INSTANCE_VARIANTS=[
  {id:"I01",zh:"标准",en:""},{id:"I02",zh:"红色",en:"red"},{id:"I03",zh:"蓝色",en:"blue"},{id:"I04",zh:"黄色",en:"yellow"},
  {id:"I05",zh:"绿色",en:"green"},{id:"I06",zh:"橙色",en:"orange"},{id:"I07",zh:"黑色",en:"black"},{id:"I08",zh:"白色",en:"white"},
  {id:"I09",zh:"灰色",en:"gray"},{id:"I10",zh:"透明",en:"transparent"},{id:"I11",zh:"大号红色",en:"large red"},{id:"I12",zh:"小号红色",en:"small red"},
  {id:"I13",zh:"大号蓝色",en:"large blue"},{id:"I14",zh:"小号蓝色",en:"small blue"},{id:"I15",zh:"高型黄色",en:"tall yellow"},{id:"I16",zh:"矮型黄色",en:"short yellow"},
  {id:"I17",zh:"宽型绿色",en:"wide green"},{id:"I18",zh:"窄型绿色",en:"narrow green"},{id:"I19",zh:"条纹白色",en:"striped white"},{id:"I20",zh:"标签灰色",en:"labeled gray"}
];

const el={grid:document.querySelector("#familyGrid"),empty:document.querySelector("#emptyState"),search:document.querySelector("#searchInput"),scene:document.querySelector("#sceneFilter"),reset:document.querySelector("#resetBtn"),dialog:document.querySelector("#familyDialog"),dialogContent:document.querySelector("#dialogContent"),close:document.querySelector("#dialogClose"),sceneDialog:document.querySelector("#sceneDialog"),sceneDialogContent:document.querySelector("#sceneDialogContent"),sceneDialogClose:document.querySelector("#sceneDialogClose")};
SCENES.forEach(scene=>el.scene.insertAdjacentHTML("beforeend",`<option value="${scene}">${scene}</option>`));

function taskMatches(f,t){const q=el.search.value.trim().toLowerCase();const text=[f.zh,f.en,f.desc,...f.examples,t.name,t.scene,t.items,t.primaryObject,t.description,t.prompt].join(" ").toLowerCase();return(el.scene.value==="all"||t.scene===el.scene.value)&&(!q||text.includes(q));}
function visibleFamilies(){return TASK_FAMILIES.map(f=>({...f,matched:f.tasks.filter(t=>taskMatches(f,t))})).filter(f=>f.matched.length);}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function splitTaskItems(items){const parts=String(items).split(/[、，,]/).map(v=>v.trim()).filter(Boolean);return{primary:parts[0]||"目标物体",parts}}
function primaryObject(task){return task.primaryObject||splitTaskItems(task.items).primary}
function fixedReferences(task){if(task.fixedObjects)return task.fixedObjects;const {parts}=splitTaskItems(task.items),primary=primaryObject(task);let removed=false;const references=parts.filter(part=>{if(!removed&&(part.includes(primary)||primary.includes(part))){removed=true;return false}return true});if(!removed)references.shift();return references.join("、")||"无固定参照物"}
function instanceObject(task,variant){const primary=primaryObject(task);return variant.en?`${variant.zh}${primary}`:primary}
function escapeRegExp(value){return String(value).replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}
function instancePrompt(task,variant){if(!variant.en)return task.prompt;const target=task.primaryObjectEn||"";if(target&&new RegExp(escapeRegExp(target),"i").test(task.prompt)){return task.prompt.replace(new RegExp(escapeRegExp(target),"i"),`${variant.en} ${target}`)}return`${task.prompt} using the ${variant.en} ${target||"object"}`}
function instanceOptions(task){return INSTANCE_VARIANTS.map((variant,index)=>`<option value="${index}">${escapeHtml(instanceObject(task,variant))}</option>`).join("")}

function render(){const list=visibleFamilies();el.grid.innerHTML="";el.empty.hidden=list.length!==0;list.forEach(f=>{const card=document.createElement("article");card.className="family-card";card.style.setProperty("--accent",accents[f.n-1]);card.tabIndex=0;card.setAttribute("role","button");card.setAttribute("aria-label",`查看 ${f.zh} 的任务`);card.innerHTML=`<span class="family-number">FAMILY ${String(f.n).padStart(2,"0")}</span><h3>${escapeHtml(f.zh)}</h3><span class="family-en">${escapeHtml(f.en)}</span><p class="family-desc">${escapeHtml(f.desc)}</p><div class="family-bottom"><strong>${f.matched.length} / 10 TASKS</strong><b>查看任务 →</b></div>`;card.addEventListener("click",()=>openFamily(f));card.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openFamily(f)}});el.grid.appendChild(card)});}

function openFamily(f){
  const tasks=f.matched||f.tasks;
  const rows=tasks.map(t=>`<article class="task-row" data-task-id="${t.id}"><div class="task-row-index">${t.id}</div><div class="task-main"><div class="task-title-line"><h3>${escapeHtml(t.name)}</h3></div><div class="task-badges"><span class="badge">${escapeHtml(f.zh)}</span><span class="badge">${escapeHtml(t.scene)}</span></div><div class="task-definition"><div class="detail task-goal-detail"><small>任务目标</small><p>${escapeHtml(t.description)}</p></div><div class="detail instance-detail"><small>物品实例</small><label class="instance-select"><select aria-label="选择 ${escapeHtml(t.name)} 的物品实例">${instanceOptions(t)}</select><i>⌄</i></label></div></div><div class="prompt"><strong>语言指令</strong><q>${escapeHtml(t.prompt)}</q></div></div></article>`).join("");
  el.dialogContent.innerHTML=`<div class="dialog-body"><span class="dialog-kicker">FAMILY ${String(f.n).padStart(2,"0")} · ${tasks.length} TASKS</span><h2>${escapeHtml(f.zh)}</h2><p class="dialog-summary"><strong>${escapeHtml(f.en)}</strong> — ${escapeHtml(f.desc)}</p><div class="task-list">${rows}</div></div>`;
  el.dialogContent.querySelectorAll(".task-row").forEach((row,index)=>{const task=tasks[index],select=row.querySelector(".instance-select select"),prompt=row.querySelector(".prompt q");select.addEventListener("change",()=>{const variant=INSTANCE_VARIANTS[Number(select.value)];prompt.textContent=instancePrompt(task,variant)})});
  el.dialog.showModal();document.body.classList.add("no-scroll");
}
function closeDialog(){el.dialog.close();document.body.classList.remove("no-scroll")}
function sceneStorageKey(sceneName){return `unitree-scene-material-links:${sceneName}`}
function defaultMaterialInstances(category){const base=String(category||"未命名物料").trim()||"未命名物料";return INSTANCE_VARIANTS.map(variant=>({id:variant.id,name:variant.en?`${variant.zh}${base}`:base,url:""}))}
function normalizeSceneMaterials(saved,defaults){if(Array.isArray(saved))return saved.map((item,index)=>{const name=String(item?.name||defaults[index]||`物料类别 ${index+1}`).trim();if(Array.isArray(item?.instances)){const instances=item.instances.map((instance,i)=>({id:instance.id||`I${String(i+1).padStart(2,"0")}`,name:String(instance.name||`${name}实例 ${i+1}`).trim(),url:String(instance.url||"").trim()}));return{name,instances:instances.length?instances:defaultMaterialInstances(name)}}const instances=defaultMaterialInstances(name);if(item?.url)instances[0].url=String(item.url).trim();return{name,instances}});if(saved&&typeof saved==="object")return defaults.map(name=>{const instances=defaultMaterialInstances(name);if(saved[name])instances[0].url=String(saved[name]).trim();return{name,instances}});return defaults.map(name=>({name,instances:defaultMaterialInstances(name)}))}
function readSceneMaterials(sceneName,defaults){try{return normalizeSceneMaterials(JSON.parse(localStorage.getItem(sceneStorageKey(sceneName))||"null"),defaults)}catch{return normalizeSceneMaterials(null,defaults)}}
function requiredSceneMaterials(sceneName){return [...new Set(TASK_FAMILIES.flatMap(f=>f.tasks).filter(task=>task.scene===sceneName).map(task=>primaryObject(task)).filter(Boolean))]}
function restoreRequiredSceneMaterials(materials,defaults){const existing=new Set(materials.map(material=>material.name));defaults.forEach(name=>{if(!existing.has(name))materials.push({name,instances:defaultMaterialInstances(name)})});return materials}
function writeSceneMaterials(sceneName,materials){try{localStorage.setItem(sceneStorageKey(sceneName),JSON.stringify(materials));return true}catch{return false}}
function safeMaterialUrl(value){const url=String(value||"").trim();return /^https?:\/\//i.test(url)?url:"#"}
function sceneText(card,selector,label){return card.querySelector(selector).textContent.trim().replace(new RegExp(`^${label}`),"").trim().replace(/。$/,"")}
function trashIcon(){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m-8 0 1 13h8l1-13M10 11v5m4-5v5"/></svg>`}
function editIcon(){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4l11-11-4-4L4 16v4Zm9-13 4 4"/></svg>`}
function checkIcon(){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>`}
function materialLinkControl(instance){const raw=String(instance.url||"").trim(),url=safeMaterialUrl(raw),linked=url!=="#";return `<div class="material-link-cell"><input class="material-url${linked?" is-linked":""}" type="url" inputmode="url" value="${escapeHtml(raw)}" placeholder="https://…" aria-label="物料链接"><a class="material-link${linked?" is-visible":""}" href="${escapeHtml(url)}" target="_blank" rel="noreferrer">${escapeHtml(raw)}</a><button type="button" class="material-link-edit${linked?" is-visible":""}">修改</button></div>`}
function materialInstanceOptions(material,selected=0){return material.instances.map((instance,i)=>`<option value="${i}"${i===selected?" selected":""}>${escapeHtml(instance.name||"未命名实例")}</option>`).join("")}
function materialInstanceEditor(material,selected=0){const instance=material.instances[selected];if(!instance)return`<div class="material-instance-empty"><span>该物料暂无实例</span><button type="button" class="material-instance-add">＋ 添加实例</button></div>`;return `<div class="material-instance-module" data-instance-index="${selected}"><label><small>物料链接</small>${materialLinkControl(instance)}</label></div>`}
function materialCategoryCard(material,i){const instance=material.instances[0];return `<article class="material-category" data-category-index="${i}"><header><span class="material-index">${String(i+1).padStart(2,"0")}</span><label><small>物料名</small><input class="material-category-name" value="${escapeHtml(material.name||"")}" placeholder="填写物料名" aria-label="物料名"></label><label><small>实例</small><div class="material-instance-control"><select class="material-instance-select" aria-label="选择 ${escapeHtml(material.name||"物料")} 的实例">${materialInstanceOptions(material)}</select><button type="button" class="material-instance-edit-trigger" aria-label="修改当前实例名称" title="修改实例名称">${editIcon()}</button><div class="material-instance-edit-box" hidden><input class="material-instance-edit-input" value="${escapeHtml(instance?.name||"")}" aria-label="修改实例名称"><button type="button" class="material-instance-edit-save" aria-label="保存实例名称" title="保存">${checkIcon()}</button></div></div></label><button type="button" class="material-instance-add icon-add" aria-label="添加实例" title="添加实例"${material.instances.length>=20?" disabled":""}>＋</button><button type="button" class="material-category-delete icon-delete" aria-label="删除 ${escapeHtml(material.name||"该物料")}" title="删除该物料">${trashIcon()}</button></header><div class="material-instance-editor">${materialInstanceEditor(material)}</div></article>`}
function openSceneDetail(card,index){
  const sceneName=card.querySelector("h3").textContent.trim();
  const baseItems=(card.dataset.materials||"").split(/[、，,]/).map(v=>v.trim()).filter(Boolean);
  const items=[...new Set([...baseItems,...requiredSceneMaterials(sceneName)])];
  let materials=restoreRequiredSceneMaterials(readSceneMaterials(sceneName,items),items);
  el.sceneDialogContent.innerHTML=`<div class="dialog-body scene-dialog-body"><span class="dialog-kicker">SCENE ${String(index+1).padStart(2,"0")} · MATERIAL REGISTER</span><h2>${escapeHtml(sceneName)}</h2><div class="material-register-head"><div><strong>场景物料</strong></div><span>INSTANCE SELECTOR</span></div><div class="material-register"></div><button type="button" class="material-add">＋ 添加物料</button><div class="material-actions"><p>物料名、实例及链接仅保存在当前浏览器，不会上传或公开。</p><span class="material-save-status" aria-live="polite"></span><button type="button" class="material-save">保存物料清单</button></div></div>`;
  const register=el.sceneDialogContent.querySelector(".material-register");
  const status=el.sceneDialogContent.querySelector(".material-save-status");
  const renderCategories=()=>{register.innerHTML=materials.map(materialCategoryCard).join("")};
  const renderEditor=(categoryCard,selected)=>{const categoryIndex=Number(categoryCard.dataset.categoryIndex),material=materials[categoryIndex],safeIndex=Math.max(0,Math.min(selected,material.instances.length-1));categoryCard.querySelector(".material-instance-editor").innerHTML=materialInstanceEditor(material,safeIndex);const selector=categoryCard.querySelector(".material-instance-select"),editBox=categoryCard.querySelector(".material-instance-edit-box"),editInput=categoryCard.querySelector(".material-instance-edit-input"),editTrigger=categoryCard.querySelector(".material-instance-edit-trigger");selector.innerHTML=materialInstanceOptions(material,safeIndex);editInput.value=material.instances[safeIndex]?.name||"";selector.hidden=false;editTrigger.hidden=false;editBox.hidden=true;categoryCard.querySelector(".material-instance-add").disabled=material.instances.length>=20};
  const activateLink=input=>{const cell=input.closest(".material-link-cell"),link=cell.querySelector(".material-link"),edit=cell.querySelector(".material-link-edit"),raw=input.value.trim(),url=safeMaterialUrl(raw);if(url==="#")return;link.href=url;link.textContent=raw;input.classList.add("is-linked");link.classList.add("is-visible");edit.classList.add("is-visible")};
  renderCategories();
  register.addEventListener("input",e=>{const categoryCard=e.target.closest(".material-category");if(!categoryCard)return;const categoryIndex=Number(categoryCard.dataset.categoryIndex),material=materials[categoryIndex];if(e.target.classList.contains("material-category-name"))material.name=e.target.value;if(e.target.classList.contains("material-url")){const instanceIndex=Number(e.target.closest(".material-instance-module").dataset.instanceIndex);material.instances[instanceIndex].url=e.target.value}status.textContent=""});
  register.addEventListener("change",e=>{if(e.target.classList.contains("material-instance-select")){renderEditor(e.target.closest(".material-category"),Number(e.target.value));status.textContent=""}});
  register.addEventListener("focusout",e=>{if(e.target.classList.contains("material-url"))activateLink(e.target)});
  register.addEventListener("keydown",e=>{if(e.target.classList.contains("material-url")&&e.key==="Enter"){e.preventDefault();activateLink(e.target)}if(e.target.classList.contains("material-instance-edit-input")&&e.key==="Enter"){e.preventDefault();e.target.closest(".material-instance-control").querySelector(".material-instance-edit-save").click()}if(e.target.classList.contains("material-instance-edit-input")&&e.key==="Escape"){e.preventDefault();renderEditor(e.target.closest(".material-category"),Number(e.target.closest(".material-category").querySelector(".material-instance-select").value))}});
  register.addEventListener("click",e=>{const categoryCard=e.target.closest(".material-category");if(!categoryCard)return;const categoryIndex=Number(categoryCard.dataset.categoryIndex),material=materials[categoryIndex];const edit=e.target.closest(".material-link-edit");if(edit){const cell=edit.closest(".material-link-cell"),input=cell.querySelector(".material-url");input.classList.remove("is-linked");cell.querySelector(".material-link").classList.remove("is-visible");edit.classList.remove("is-visible");input.focus();input.select();return}if(e.target.closest(".material-instance-edit-trigger")){const selector=categoryCard.querySelector(".material-instance-select"),editBox=categoryCard.querySelector(".material-instance-edit-box"),editInput=categoryCard.querySelector(".material-instance-edit-input");selector.hidden=true;e.target.closest(".material-instance-edit-trigger").hidden=true;editBox.hidden=false;editInput.value=material.instances[Number(selector.value)]?.name||"";editInput.focus();editInput.select();return}if(e.target.closest(".material-instance-edit-save")){const selector=categoryCard.querySelector(".material-instance-select"),selected=Number(selector.value),value=categoryCard.querySelector(".material-instance-edit-input").value.trim();if(material.instances[selected])material.instances[selected].name=value||"未命名实例";renderEditor(categoryCard,selected);status.textContent="";return}if(e.target.closest(".material-category-delete")){materials.splice(categoryIndex,1);renderCategories();status.textContent="";return}if(e.target.closest(".material-instance-add")){const used=new Set(material.instances.map(instance=>instance.id));let n=1;while(used.has(`I${String(n).padStart(2,"0")}`))n++;const id=`I${String(n).padStart(2,"0")}`;material.instances.push({id,name:`${material.name||"具体物料"}实例 ${String(n).padStart(2,"0")}`,url:""});renderEditor(categoryCard,material.instances.length-1);status.textContent=""}});
  el.sceneDialogContent.querySelector(".material-add").addEventListener("click",()=>{const name="新物料";materials.push({name,instances:defaultMaterialInstances(name)});renderCategories();register.lastElementChild.querySelector(".material-category-name").focus();status.textContent=""});
  el.sceneDialogContent.querySelector(".material-save").addEventListener("click",()=>{materials=materials.map(material=>({name:String(material.name||"").trim(),instances:material.instances.map(instance=>({id:instance.id,name:String(instance.name||"").trim(),url:String(instance.url||"").trim()}))})).filter(material=>material.name||material.instances.length);const ok=writeSceneMaterials(sceneName,materials);status.textContent=ok?"已保存":"浏览器未允许本地保存"});
  el.sceneDialog.showModal();document.body.classList.add("no-scroll");
}
function closeSceneDialog(){el.sceneDialog.close();document.body.classList.remove("no-scroll")}
document.querySelectorAll(".scene-card").forEach((card,index)=>{const trigger=document.createElement("button");trigger.type="button";trigger.className="scene-detail-trigger";trigger.innerHTML="<span>物料配置</span><b>→</b>";trigger.addEventListener("click",()=>openSceneDetail(card,index));card.appendChild(trigger)});
function reset(){el.search.value="";el.scene.value="all";render()}
render();[el.search,el.scene].forEach(x=>x.addEventListener(x===el.search?"input":"change",render));el.reset.addEventListener("click",reset);el.close.addEventListener("click",closeDialog);el.dialog.addEventListener("click",e=>{if(e.target===el.dialog)closeDialog()});el.sceneDialogClose.addEventListener("click",closeSceneDialog);el.sceneDialog.addEventListener("click",e=>{if(e.target===el.sceneDialog)closeSceneDialog()});document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(el.sceneDialog.open)closeSceneDialog();else if(el.dialog.open)closeDialog()}});
